    [18363] = { 11689, 2, 64, "Kodo de montar", "\"El kodo es la columna vertebral de nuestro pueblo. Dondequiera que vaya la Horda, ya sea en el comercio, en los asentamientos o en la guerra, allí encontrarás al poderoso kodo\". - Harb Pezuña Crecida", 2, "|cFFFFD200Legado|r" },
