    [22717] = { 14332, 2, 0, "Corcel de guerra negro", "Entrenado para soportar brutales combates cuerpo a cuerpo en los campos de batalla más encarnizados.", 2, "|cFFFFD200Vendedor: |rTeniente Karter|n|cFFFFD200Zona: |rCiudad de Ventormenta|n|cFFFFD200Coste: |r50000|TInterface\\PVPFrame\\PVP-Currency-Alliance:0|t" },
    [22718] = { 14333, 2, 0, "Kodo de guerra negro", "Criados por su temperamento agresivo e impredecible por los maestros de establo Kor'kron, el bramido del kodo de guerra negro indica que pronto se derramará sangre.", 2, "|cFFFFD200Vendedor: |rIncursor Bork|n|cFFFFD200Zona: |rOrgrimmar|n|cFFFFD200Coste: |r50000|TInterface\\PVPFrame\\PVP-Currency-Horde:0|t" },
    [22719] = { 14334, 2, 0, "Zancudo de batalla negro", "Un gnomo debidamente acelerado en la batalla es algo de una belleza terrible. - Manitas Mayor Mekkatorque", 2, "|cFFFFD200Vendedor: |rTeniente Karter|n|cFFFFD200Zona: |rCiudad de Ventormenta|n|cFFFFD200Coste: |r50000|TInterface\\PVPFrame\\PVP-Currency-Alliance:0|t" },
    [22720] = { 14335, 2, 0, "Carnero de guerra negro", "Los enanos valoran a sus compañeros carneros por su intrepidez al cargar hacia la batalla.", 2, "|cFFFFD200Vendedor: |rTeniente Karter|n|cFFFFD200Zona: |rCiudad de Ventormenta|n|cFFFFD200Coste: |r50000|TInterface\\PVPFrame\\PVP-Currency-Alliance:0|t" },
    [22721] = { 14330, 2, 0, "Raptor de guerra negro", "Criado del mismo linaje feroz de raptores que engendró a Ohgan y llevó la victoria al Imperio Gurubashi.", 2, "|cFFFFD200Vendedor: |rIncursor Bork|n|cFFFFD200Zona: |rOrgrimmar|n|cFFFFD200Coste: |r50000|TInterface\\PVPFrame\\PVP-Currency-Horde:0|t" },
