    [41513] = { 23455, 1, 128, "Draco Ala Abisal ónice", "Tras prometer llevarte volando hasta los confines de Terrallende, el draco Ala Abisal finalmente se sintió atraído también por los cielos azules de Azeroth.", 1, "|cFFFFD200Misión: |rOnyxien el draco Ala Abisal ónice|n|cFFFFD200Zona: |rCiudad de Shattrath, Terrallende" },
