    [42776] = { 24003, 2, 64, "Tigre espectral", "Al más puro estilo goblin, Landro Tirofeliz ha monopolizado la distribución de estas misteriosas monturas incorpóreas.", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r Tigre espectral" },
    [42777] = { 24004, 2, 64, "Tigre espectral presto", "Los historiadores afirman que estas bestias incorpóreas se crearon cuando Draenor explotó, liberando energías que distorsionaron la flora y fauna del mundo.", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r Tigre espectral" },
