    [43899] = { 23588, 2, 64, "Carnero de la Fiesta de la Cerveza", "Los cerveceros retiraron esta montura del servicio publicitario activo tras quejas de que las bestias eran \"demasiado temperamentales\" para controlarlas en las ciudades principales.", 6, "|cFFFFD200Legado|r" },
    [43900] = { 24368, 2, 0, "Carnero de la Fiesta de la Cerveza presto", "Los enanos atribuyen el temperamento uniforme de esta raza a un entrenamiento riguroso, pero otras razas sostienen que una dieta diaria de cerveza fuerte tiene algo que ver.", 0, "|cFFFFD200Botín:|r Cofre del tesoro con forma de barril|n|cFFFFD200Festividad:|r Fiesta de la Cerveza" },
    [43927] = { 24488, 1, 128, "Hipogrifo de guerra Cenarion", "Los miembros del Círculo Cenarion han compartido una larga y próspera asociación con sus aliados hipogrifos. Cuando el conflicto es inevitable, el hipogrifo de guerra Cenarion entra en servicio.", 2, "|cFFFFD200Vendedor: |rFedryen Lanza Presta|n|cFFFFD200Zona: |rMarisma de Zangar, Terrallende|n|cFFFFD200Facción: |rExpedición Cenarion - Exaltado|n|cFFFFD200Coste: |r2000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [44151] = { 24654, 1, 128, "Máquina voladora propulsada", "Solo los ingenieros con más talento tienen el coraje y la resistencia mental para crear una máquina voladora que presuma de estabilidad y seguridad. ¡Propulsarla es una auténtica locura!", 3, "|cFFFFD200Profesión: |rIngeniería" },
    [44153] = { 24653, 1, 128, "Máquina voladora", "La columna vertebral de la fuerza aérea de la Alianza está compuesta predominantemente por máquinas voladoras gnómicas debido a su maniobrabilidad y velocidad.", 3, "|cFFFFD200Profesión: |rIngeniería" },
