    [48027] = { 26439, 2, 0, "Elekk de guerra negro", "Los toros elekk excepcionalmente agresivos y belicosos se separan de la manada y se venden a comerciantes etéreos. Los comerciantes luego entrenan a los toros para el combate y los venden a dueños despreocupados por la seguridad.", 2, "|cFFFFD200Vendedor: |rTeniente Karter|n|cFFFFD200Zona: |rCiudad de Ventormenta|n|cFFFFD200Coste: |r50000|TInterface\\PVPFrame\\PVP-Currency-Alliance:0|t" },
    [48778] = { 28302, 2, 0, "Destrero de la muerte de Acherus", "Algunos caballos simplemente adoptan la oscuridad. Este caballo nació en ella, moldeado por ella.", 2, "|cFFFFD200Instructor:|r Caballero de la Muerte|n" },
