    [49379] = { 27707, 2, 0, "Gran kodo de la Fiesta de la Cerveza", "Coren Cerveza Temible ganó este premio tras tumbar bebiendo a un druida tauren, y el druida estaba en forma de oso. Fue uno de los momentos más memorables de Cerveza Temible.", 0, "|cFFFFD200Botín:|r Cofre del tesoro con forma de barril|n|cFFFFD200Festividad:|r Fiesta de la Cerveza" },
