    [54729] = { 29582, 1, 128, "Corcel alado de la Espada de Ébano", "Vivo o muerto, vendrás conmigo.", 2, "|cFFFFD200Vendedor: |rComandante del Terror Thalanor|n|cFFFFD200Zona: |rTierras de la Peste del Este|n|cFFFFD200Coste: |r1000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [54753] = { 29596, 2, 0, "Oso polar blanco", "Los vrykul de escarcha creen que llevar un collar de garras de oso polar les otorgará una fuerza sobrenatural.", 0, "|cFFFFD200Botín:|r Botín Hyldnir|n|cFFFFD200Ubicación:|r Las Cumbres Tormentosas" },
    [55164] = { 29767, 2, 64, "Grifo espectral presto", "Incluso los muertos necesitan que los lleven de vez en cuando.", 5, "|cFFFFD200Legado|r" },
    [55293] = { 24379, 2, },
    [55531] = { 29929, 2, 4, "Mechano-Hog", "Difíciles de construir y mantener, estas motos compensan con creces su coste a través de su innegable estilo.", 3, "|cFFFFD200Profesión: |rIngeniería" },
    [58615] = { 31124, 1, 192, "Draco abisal brutal", "Los dracos abisales más agresivos se otorgaron a los héroes que demostraron una notable destreza y compromiso en la arena de gladiadores.", 2, "|cFFFFD200Legado|r" },
    [58819] = { 14561, 2, },
    [58983] = { 31319, 2, 0, "Gran oso de Blizzard", "Cada vez que montas en este oso, sientes la necesidad de gritar: \"¡Desatad el caos y soltad a los múrlocs de la guerra!\"", 7, "|cFFFFD200Promoción:|r BlizzCon|n" },
    [58997] = { 31319, 2, },
    [58999] = { 31319, 2, },
    [59567] = { 31694, 1, 128, "Draco azur", "Habla siempre con educación a un dragón enfurecido.", 0, "|cFFFFD200Botín:|r Regalo de Alexstrasza|n|cFFFFD200Ubicación:|r El Ojo de la Eternidad" },
    [59568] = { 31695, 1, 128, "Draco azul", "No te interpongas entre el dragón y su ira.", 0, "|cFFFFD200Botín:|r Regalo de Alexstrasza|n|cFFFFD200Ubicación:|r El Ojo de la Eternidad" },
    [59569] = { 31717, 1, 128, "Draco bronce", "El tiempo perdido nunca se recupera. Bueno, no importa, ya lo encontré. -Cromi", 0, "|cFFFFD200Botín: |rCorruptor Infinito|n|cFFFFD200Zona: |rLa Matanza de Stratholme" },
    [59570] = { 31697, 1, 128, "Draco rojo", "Nunca deberías escuchar las fantasías de los juglares. Un dragón nunca dañaría a nadie, a menos que intentaran dañarlo a él primero.", 2, "|cFFFFD200Vendedor: |rCielstrasza|n|cFFFFD200Zona: |rCementerio de Dragones|n|cFFFFD200Facción: |rEl Reposo del Dragón - Exaltado|n|cFFFFD200Coste: |r2000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [59571] = { 31698, 1, 128, "Draco crepuscular", "Pero la regla más importante, la regla que nunca puedes olvidar, sin importar cuánto llore o cuánto suplique, es nunca darle de comer después de medianoche.", 0, "|cFFFFD200Botín:|r Sartharion|n|cFFFFD200Ubicación:|r El Sagrario Obsidiana" },
    [59572] = { 31699, 2, 64, "Oso polar negro", "Los taunka usan pieles de oso polar negro en sus ritos religiosos, normalmente en los funerales de aquellos que cazan osos polares negros.", 2, "|cFFFFD200Legado|r" },
    [59573] = { 31700, 2, },
    [59650] = { 31778, 1, 128, "Draco negro", "Nunca compensa dejar a un dragón vivo fuera de la ecuación.", 0, "|cFFFFD200Botín:|r Sartharion" },
    [59785] = { 31849, 2, 4, "Mamut de guerra negro", "Normalmente bestias plácidas, estos animales inteligentes forman un fuerte vínculo con sus jinetes, haciéndolos leales e intrépidos en la batalla.", 2, "|cFFFFD200Vendor: |rKnight Dameron|n|cFFFFD200Zone: |rWintergrasp|n|cFFFFD200Cost: |r300|Hitem:43228|h|TInterface\\ICONS\\INV_Misc_Platnumdisks:0|t|h" },
    [59788] = { 31850, 2, 4, "Mamut de guerra negro", "De paso firme e imperturbables, estos mamuts de pelaje oscuro son apreciados por su temperamento estable al entrar en combate.", 2, "|cFFFFD200Vendor: |rStone Guard Mukar|n|cFFFFD200Zone: |rWintergrasp|n|cFFFFD200Cost: |r300|Hitem:43228|h|TInterface\\ICONS\\INV_Misc_Platnumdisks:0|t|h" },
    [59791] = { 31851, 2, 4, "Mamut lanudo", "Descendientes directos del progenitor original de la raza de mamuts, se considera que los mamuts lanudos son más salvajes y primitivos que sus primos de pelo más corto.", 2, "|cFFFFD200Vendedor: |rMei Francis|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r200|TINTERFACE\\ICONS\\Spell_Holy_ProclaimChampion:0|t" },
    [59793] = { 31852, 2, 4, "Mamut lanudo", "Esta variante salvaje del mamut no está criada para montar. La mayoría de los mamuts lanudos son capturados en estado salvaje y domados por sus jinetes, resultando en una montura feroz y astuta.", 2, "|cFFFFD200Vendedor: |rMei Francis|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r200|TINTERFACE\\ICONS\\Spell_Holy_ProclaimChampion:0|t" },
    [59797] = { 31854, 2, 4, "Mamut de hielo", "Los Hijos de Hodir creen que montar un mamut blanco como el hielo protegerá al jinete de la congelación y la ceguera de la nieve.", 2, "|cFFFFD200Vendedor: |rLillehoff|n|cFFFFD200Zona: |rLas Cumbres Tormentosas|n|cFFFFD200Facción: |rLos Hijos de Hodir - Venerado|n|cFFFFD200Coste: |r1000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [59799] = { 31855, 2, 4, "Mamut de hielo", "Muchos gigantes de hielo afirman que han entrenado a sus mamuts blancos predilectos para provocar avalanchas con sus bramidos.", 2, "|cFFFFD200Vendedor: |rLillehoff|n|cFFFFD200Zona: |rLas Cumbres Tormentosas|n|cFFFFD200Facción: |rLos Hijos de Hodir - Venerado|n|cFFFFD200Coste: |r1000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [59802] = { 31857, 2, },
    [59804] = { 31858, 2, },
    [59961] = { 31902, 1, 128, "Protodraco rojo", "Los vrykul fueron los primeros en reconocer su potencial. O tal vez los segundos, según como se mire.", 5, "|cFFFFD200Logro: |rLa gloria del héroe|n|cFFFFD200Categoría: |rMazmorras y bandas" },
    [59976] = { 31912, 1, 192, "Protodraco negro", "Criado específicamente para honrar a aquellos héroes que demostraron una resistencia y entereza excepcionales frente a los peligros de Rasganorte.", 2, "|cFFFFD200Legado|r" },
    [59996] = { 32151, 1, 128, "Protodraco azul", "¡Las Cumbres Tormentosas! Allí encontraremos la bestia lo bastante fuerte como para llevarme a la batalla. -Skadi el Despiadado", 0, "|cFFFFD200Botín: |rSkadi el Despiadado|n|cFFFFD200Zona: |rPináculo de Utgarde" },
    [60002] = { 32153, 1, 128, "Protodraco del Tiempo Perdido", "La única razón de la existencia del tiempo es para que todo no suceda a la vez.", 0, "|cFFFFD200Botín: |rProtodraco del Tiempo Perdido|n|cFFFFD200Zona: |rLas Cumbres Tormentosas" },
    [60021] = { 32156, 1, 192, "Protodraco apestado", "Criado específicamente para honrar a aquellos héroes que demostraron un coraje y persistencia notables frente a los peligros de Rasganorte.", 5, "|cFFFFD200Legado|r" },
    [60024] = { 32157, 1, 128, "Protodraco violeta", "No puedo evitar preguntarme si las cosas habrían sido diferentes si los titanes hubieran elevado siquiera a un vuelo de dragones más. -Alexstrasza", 5, "|cFFFFD200Logro: |rHa sido un largo y raro viaje|n|cFFFFD200Categoría: |rEventos del mundo" },
    [60025] = { 32158, 1, 128, "Draco albino", "Incluso las pruebas de la Asociación Nativa Dracónica resultaron no concluyentes para determinar si el draco albino está emparentado con un vuelo de dragones conocido. -Breanni", 5, "|cFFFFD200Logro: |rA la cabeza de la caballería|n|cFFFFD200Categoría: |rGeneral" },
    [60114] = { 32206, 2, 4, "Oso marrón acorazado", "La rapidez de esta montura ursina se ve reforzada por su pesada armadura, impregnada de magia por los magos del Kirin Tor.", 2, "|cFFFFD200Vendedor: |rMei Francis|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r750|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [60116] = { 32207, 2, 4, "Oso marrón acorazado", "Tus gritos de \"¡Por la Horda!\" serán mucho más amenazantes a lomos de un oso fuertemente acorazado que carga contra la Alianza a toda velocidad.", 2, "|cFFFFD200Vendedor: |rMei Francis|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r750|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [60118] = { 32203, 2, 4, "Oso de guerra negro", "Matar a los líderes de la Horda es su propia recompensa, pero esta intimidante bestia es un excelente recuerdo.", 5, "|cFFFFD200Logro: |r¡Por la Alianza!|n|cFFFFD200Categoría: |rJugador contra Jugador" },
    [60119] = { 32205, 2, 4, "Oso de guerra negro", "Esta formidable montura se compra con la sangre de los líderes de la Alianza, pero los habrías matado gratis.", 5, "|cFFFFD200Logro: |r¡Por la Horda!|n|cFFFFD200Categoría: |rJugador contra Jugador" },
    [60120] = { 32208, 1, },
    [60136] = { 32212, 0, 64, "Gran mamut de caravana", "Los mercaderes solo confían en este imponente y montañoso corcel para protegerse cuando se aventuran por las rutas comerciales más peligrosas de Azeroth.", 2, "|cFFFFD200Legado|r" },
    [60140] = { 32213, 0, 64, "Gran mamut de caravana", "Una estampa habitual en las rutas comerciales de todo Azeroth, esta montura tranquila y leal es la favorita de los mercaderes que viajan a mercados exóticos y lejanos.", 2, "|cFFFFD200Legado|r" },
    [60424] = { 32286, 2, 4, "Chopper de meganiñero", "Con una magnífica artesanía de ingeniería, esta chopper es uno de los pocos vehículos personales de Azeroth construido para dos personas.", 3, "|cFFFFD200Profesión: |rIngeniería" },
    [61229] = { 32335, 1, 132, "Grifo nevado acorazado", "Lo bueno es que cuando atacan, la sangre casi nunca mancha sus plumas. -Mei Francis", 2, "|cFFFFD200Vendedor: |rMei Francis|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r2000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [61230] = { 32336, 1, 132, "Jinete del viento azul acorazado", "No son nativos de Rasganorte, pero se han adaptado sumamente bien al frío. -Mei Francis", 2, "|cFFFFD200Vendedor: |rMei Francis|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r2000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [61289] = { 23966, 0, },
    [61294] = { 32562, 1, 128, "Protodraco verde", "Los vrykul fueron los primeros en reconocer su potencial. O tal vez los segundos, según como se mire.", 0, "|cFFFFD200Botín:|r Huevo agrietado" },
    [61309] = { 33030, 1, 1024, "Alfombra voladora magnífica", "Las características estándar incluyen un armazón resistente impregnado de tejido de escarcha e hilo de seda de araña telahielo auténtica. El cojín de repuesto se vende por separado.", 3, "|cFFFFD200Profesión: |rSastrería" },
    [61425] = { 32633, 2, 4, "Mamut de tundra de viajero", "Antiguos manuscritos representan a mercaderes viajando por la tundra helada con estas colosales bestias, lo que lleva a los eruditos a creer que son las primeras monturas domesticadas.", 2, "|cFFFFD200Vendedor: |rMei Francis|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r20000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [61442] = { 32634, 1, },
    [61444] = { 32635, 1, },
    [61446] = { 32636, 1, },
    [61447] = { 32640, 2, 4, "Mamut de tundra de viajero", "Tanto jinetes como mercaderes solo confían en este mamut fuerte y leal para transportarlos con seguridad a través de la gélida tundra.", 2, "|cFFFFD200Vendedor: |rMei Francis|n|cFFFFD200Zona: |rDalaran|n|cFFFFD200Coste: |r20000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [61451] = { 33029, 1, 1024, "Alfombra voladora", "Sube a bordo de esta alfombra voladora para contemplar el espléndido, brillante y resplandeciente mundo de Azeroth, maravilla tras maravilla.", 3, "|cFFFFD200Profesión: |rSastrería" },
    [61465] = { 31862, 2, 4, "Gran mamut de guerra negro", "Utilizados antaño por gigantes para transportar guerreros fuertemente armados, estos grandes mamuts de guerra pueden llevar fácilmente a más de un jinete de estatura menos que gigante.", 0, "|cFFFFD200Botín: |rBotín de jefe|n|cFFFFD200Ubicación: |rLa Cámara de Archavon" },
    [61467] = { 31861, 2, 4, "Gran mamut de guerra negro", "Rara vez un mamut de guerra nace más fuerte y dócil que sus congéneres. Estos mamuts son llamados \"grandes\" y transportan a más de un jinete al frente de batalla.", 0, "|cFFFFD200Botín: |rBotín de jefe|n|cFFFFD200Ubicación: |rLa Cámara de Archavon" },
    [61469] = { 31857, 2, 4, "Gran mamut de hielo", "Como en casa por los estrechos y helados senderos de Las Cumbres Tormentosas, estos mamuts son las únicas monturas en las que los gigantes de hielo confían para transportar grandes cargas y múltiples jinetes.", 2, "|cFFFFD200Vendedor: |rLillehoff|n|cFFFFD200Zona: |rLas Cumbres Tormentosas|n|cFFFFD200Facción: |rLos Hijos de Hodir - Exaltado|n|cFFFFD200Coste: |r10000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [61470] = { 31858, 2, 4, "Gran mamut de hielo", "Debido a los fuertes vientos y las avalanchas, los Hijos de Hodir recomiendan llevar al menos a dos compañeros si te aventuras en las peligrosas Cumbres Tormentosas.", 2, "|cFFFFD200Vendedor: |rLillehoff|n|cFFFFD200Zona: |rLas Cumbres Tormentosas|n|cFFFFD200Facción: |rLos Hijos de Hodir - Exaltado|n|cFFFFD200Coste: |r10000|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [61983] = { 32931, 0, },
    [61996] = { 31239, 1, 132, "Dracohalcón azul", "Los dracohalcones se encuentran entre los depredadores más letales que se conocen. Son capaces de detectar presas a grandes distancias, abalanzarse y desgarrar tanto con garras como con el pico.", 5, "|cFFFFD200Logro: |rMontón de monturas|n|cFFFFD200Categoría: |rGeneral" },
    [61997] = { 32944, 1, 132, "Dracohalcón rojo", "Los dracohalcones se encuentran entre los depredadores más letales que se conocen. Son capaces de detectar presas a grandes distancias, abalanzarse y desgarrar tanto con garras como con el pico.", 5, "|cFFFFD200Logro: |rMontón de monturas|n|cFFFFD200Categoría: |rGeneral" },
    [62048] = { 25064, 1, 192, "Halcón de la fatalidad Illidari", "Una vez al año se abre una falla en el tiempo y ocurren cosas extrañas. Los exploradores Illidari y el Caminante del Destino se sorprendieron bastante al encontrarse en Tanaris.", 0, "|cFFFFD200Botín: |rCaminante del Destino|n|cFFFFD200Zona: |rTanaris" },
    [63232] = { 33297, 2, 0, "Corcel de Ventormenta", "Aunque criada en Ventormenta, esta raza mostró una aptitud inusual para el clima gélido de Corona de Hielo.", 2, "|cFFFFD200Vendedor: |rCabo Arthur Flew|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63635] = { 33299, 2, 0, "Raptor Lanza Negra", "Esta raza de raptores fue cultivada originalmente por los Drakkari, pero desde entonces ha sido adoptada por la tribu Lanza Negra en Rasganorte.", 2, "|cFFFFD200Vendedor: |rSamamba|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63636] = { 33408, 2, 0, "Carnero de Forjaz", "El Verificador de Datos Martillo Salvaje afirma que esta raza específica fue el primer tipo de carnero domesticado por los enanos cuando se establecieron en Dun Morogh.", 2, "|cFFFFD200Vendedor: |rDerrick Barbanevada|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63637] = { 33298, 2, 0, "Sable nocturno darnassiano", "Cuando la montura de un elfo de la noche perece, es costumbre que el jinete conserve uno de los grandes colmillos del sable como muestra de recuerdo.", 2, "|cFFFFD200Vendedor: |rRook Puñohalcón|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63638] = { 33301, 2, 0, "Mecanostruz de Gnomeregan", "Cuando tienes que estar allí ahora mismo, sin excusas ni demoras. -Rillie Ejeplata", 2, "|cFFFFD200Vendedor: |rRillie Ejeplata|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63639] = { 33416, 2, 0, "Elekk del Exodar", "Los elekk del Exodar son ejemplares ungidos por O'ros, el naaru que viajó desde Draenor hasta Azeroth con Velen y sus seguidores.", 2, "|cFFFFD200Vendedor: |rIrisee|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63640] = { 33409, 2, 0, "Lobo de Orgrimmar", "Durante un breve tiempo, muchos orcos se declaraban \"hambrientos como un lobo de Orgrimmar\". Algunos elfos de sangre todavía usan la frase de forma irónica.", 2, "|cFFFFD200Vendedor: |rFreka Hachasangre|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63641] = { 33300, 2, 0, "Kodo de Cima del Trueno", "Un miembro alfa de la manada, este kodo es un excelente ejemplo de las poderosas criaturas que retumban por Mulgore.", 2, "|cFFFFD200Vendedor: |rDoru Cuernotrueno|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63642] = { 33418, 2, 0, "Halcón zancudo de Lunargenta", "Así que dije que hoy me apetecía pollo. Lo siguiente que recuerdo es estar en el suelo y ese bicho intentando ver a qué saben mis ojos. -Bozzle Chispatuerca", 2, "|cFFFFD200Vendedor: |rTrellis Solmatutino|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63643] = { 33414, 2, 0, "Caballo de guerra Renegado", "Cuando los héroes caídos son alzados en la no-muerte, también lo son sus caballos.", 2, "|cFFFFD200Vendedor: |rEliza Killian|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [63796] = { 33848, 1, 128, "Cabeza de Mimiron", "Una muestra de artesanía de los titanes acaparada por el Dios Antiguo Yogg-Saron. Actualmente la cabeza mecánica de gnomo individual más grande de Azeroth.", 0, "|cFFFFD200Botín:|r Yogg-Saron|n|cFFFFD200Ubicación:|r Ulduar" },
    [63844] = { 33857, 1, 128, "Hipogrifo argenta", "Los hipogrifos argenta solo se alían con los campeones más valientes y curtidos en la batalla.", 2, "|cFFFFD200Vendedor: |rIntendentes de facción|n|cFFFFD200Ubicación: |rTorneo Argenta, Corona de Hielo|n|cFFFFD200Coste: |r150|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t|n" },
    [63956] = { 33892, 1, 128, "Protodraco vinculado al hierro", "Su piel era más dura que el latón, tal que ni espada ni lanza podían perforarla ni herirla.", 5, "|cFFFFD200Logro: |rLa gloria del bandido de Ulduar (25 jugadores)|n|cFFFFD200Categoría: |rMazmorras y bandas" },
    [63963] = { 33904, 1, 128, "Protodraco herrumbrado", "No es tan brillante como el otro, pero sigue siendo un gran hallazgo, muchachos. -Brann Barbabronce", 5, "|cFFFFD200Logro: |rLa gloria del bandido de Ulduar (10 jugadores)|n|cFFFFD200Categoría: |rMazmorras y bandas" },
    [64656] = { 34154, 2, 64, "Caballo de guerra esquelético azul", "Un espécimen raro. La mayoría desaparecieron una vez que el barón Rivendare gobernó en Stratholme.", 2, "|cFFFFD200Legado|r" },
    [64657] = { 34155, 2, 0, "Kodo blanco", "\"El kodo es la columna vertebral de nuestro pueblo. Dondequiera que vaya la Horda, ya sea en el comercio, en los asentamientos o en la guerra, allí encontrarás al poderoso kodo\". - Harb Pezuña Crecida", 2, "|cFFFFD200Vendedor: |rHarb Pezuña Crecida|n|cFFFFD200Zona: |rMulgore|n|cFFFFD200Coste: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [64658] = { 356, 2, 0, "Lobo negro", "Puede aullar con tanta fuerza como para ser escuchado a kilómetros de distancia.", 2, "|cFFFFD200Vendedor: |rOgunaro Correlobo|n|cFFFFD200Zona: |rOrgrimmar|n|cFFFFD200Coste: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [64659] = { 34156, 2, 4, "Ravasaurio pellejo venenoso", "Criaste a este bicho desde que era una cría escamosa; Mor'vek estaría muy orgulloso. Aunque aún te obligaría a limpiar el desastre que hizo en la esquina.", 1, "|cFFFFD200Misión: |rCrecen tan rápido|n|cFFFFD200Zona: |rCráter de Un'Goro" },
    [64681] = { 32198, 1, },
    [64731] = { 34187, 2, 2192, "Tortuga de mar", "A menudo capturadas por pescadores a temprana edad, estas monturas se sienten mucho más cómodas en el agua que en tierra firme.", 3, "|cFFFFD200Profesión:|r Pesca|n" },
    [64761] = { 32208, 1, },
    [64927] = { 34225, 1, 192, "Fiel vástago de escarcha mortal", "Estas vasijas de destrucción reanimadas no temen a la muerte; la reparten.", 2, "|cFFFFD200Legado|r" },
    [64977] = { 34238, 2, 0, "Caballo esquelético negro", "Los Renegados creen que sin un propósito, incluso las bestias de carga sufren en la no-muerte.", 2, "|cFFFFD200Vendedor: |rZachariah Post|n|cFFFFD200Zona: |rClaros de Tirisfal|n|cFFFFD200Coste: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [64992] = { 31319, 2, },
    [64993] = { 31319, 2, },
    [65439] = { 34425, 1, 192, "Fiel vástago de escarcha furioso", "Algunos de los dragones más poderosos de Azeroth han sido invocados a través del velo entre la vida y la muerte para servir a nuevos amos con lealtad eterna.", 2, "|cFFFFD200Legado|r" },
    [65637] = { 34551, 2, 0, "Gran elekk rojo", "Nunca vistos en Nagrand, las primeras crías de elekk rojo nacieron en Azeroth tras la llegada del Exodar. Algunos criadores teorizan que la coloración única se debe de algún modo a la misma radiación que asoló la Isla Bruma de Sangre.", 2, "|cFFFFD200Vendedor: |rIrisee|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t5|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [65638] = { 34550, 2, 0, "Sable lunar presto", "Muchos elfos de la noche veneran a estas orgullosas monturas porque sus pelajes brillantes simbolizan a la diosa de la luna, Elune.", 2, "|cFFFFD200Vendedor: |rRook Puñohalcón|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t5|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [65639] = { 34556, 2, 0, "Halcón zancudo rojo presto", "¿A qué te refieres con si está teñido? Ah, el pájaro. Retocamos el rojo solo un poquito. -Trellis Solmatutino", 2, "|cFFFFD200Vendedor: |rTrellis Solmatutino|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t5|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [65640] = { 34557, 2, 0, "Corcel gris presto", "Un veterano de algunas de las batallas más duras libradas por la Cruzada Argenta.", 2, "|cFFFFD200Vendedor: |rCabo Arthur Flew|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t5|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [65641] = { 34558, 2, 4, "Gran kodo dorado", "Un miembro alfa de la manada, este kodo es un excelente ejemplo de las poderosas criaturas que retumban por Los Baldíos del Sur.", 2, "|cFFFFD200Vendedor: |rDoru Cuernotrueno|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t5|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [65642] = { 34553, 2, 0, "Turbostruz", "El espejo no es para que mires hacia atrás, sino para que tus enemigos puedan ver algo más que tus tubos de escape. -Rillie Ejeplata", 2, "|cFFFFD200Vendedor: |rRillie Ejeplata|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t5|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [65643] = { 34554, 2, 0, "Carnero violeta presto", "El grueso cráneo óseo y los enormes cuernos del carnero Barak Tor'ol lo convierten en la montura ideal para cargar contra grupos de enemigos blindados.", 2, "|cFFFFD200Vendedor: |rDerrick Barbanevada|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t5|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [65644] = { 34549, 2, 0, "Raptor morado presto", "Aliados tradicionales de los trolls, estos cazadores de la jungla forman un vínculo especial con sus amos. Se convierten en montura, guardián y amigo.", 2, "|cFFFFD200Vendedor: |rSamamba|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t5|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [65645] = { 34552, 2, 0, "Caballo de guerra esquelético blanco", "Cuando los héroes caídos son alzados en la no-muerte, también lo son sus caballos.", 2, "|cFFFFD200Vendedor: |rEliza Killian|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t5|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [65646] = { 34555, 2, 0, "Lobo burdeos presto", "Los lobos de la Horda son amigos, no animales domesticados.", 2, "|cFFFFD200Vendedor: |rFreka Hachasangre|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r500|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t5|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [65917] = { 34655, 2, 64, "Gallo mágico", "La magia en manos de un genio puede hacer cosas maravillosas y milagrosas. La magia en manos de un idiota puede crear un gallo gigante.", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r El Pollo Grande" },
    [66087] = { 35147, 1, 132, "Hipogrifo del Pacto de Plata", "Los hipogrifos del Pacto de Plata son ferozmente leales, tanto a sus jinetes como a la Alianza.", 2, "|cFFFFD200Vendedor: |rHiren Cantosolemnis|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Facción: |rEl Pacto de Plata - Exaltado|n|cFFFFD200Coste: |r150|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [66088] = { 35148, 1, 132, "Dracohalcón de los Atracasol", "Los Atracasol de Dalaran seleccionan solo a los dracohalcones más rápidos y formidables como sus monturas.", 2, "|cFFFFD200Vendor: |rVasarin Redmorn|n|cFFFFD200Zone: |rIcecrown|n|cFFFFD200Faction: |rThe Sunreavers - Exalted|n|cFFFFD200Cost: |r150|Hcurrency:241|h|TInterface\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t|h" },
    [66090] = { 33840, 2, 4, "Corcel Quel'dorei", "Procede de un linaje de magníficos caballos que antaño pastaban cerca de las orillas de la Fuente de la Eternidad.", 2, "|cFFFFD200Vendedor: |rHiren Cantosolemnis|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Facción: |rEl Pacto de Plata - Exaltado|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [66091] = { 33841, 2, 4, "Halcón zancudo de los Atracasol", "Exijo velocidad, gracia y disciplina en el campo de batalla. Este servirá estupendamente. -Eressea Cantodelalba", 2, "|cFFFFD200Vendor: |rVasarin Redmorn|n|cFFFFD200Zone: |rIcecrown|n|cFFFFD200Faction: |rThe Sunreavers - Exalted|n|cFFFFD200Cost: |r100|Hcurrency:241|h|TInterface\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t|h" },
