    [66846] = { 35169, 2, 0, "Caballo de guerra esquelético ocre", "Cuando los héroes caídos son alzados en la no-muerte, también lo son sus caballos.", 2, "|cFFFFD200Vendedor: |rZachariah Post|n|cFFFFD200Zona: |rClaros de Tirisfal|n|cFFFFD200Coste: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [66847] = { 35168, 2, 0, "Sable del alba a rayas", "Los elfos de la noche creían antaño que ver a esta raza de sable de color claro en estado salvaje era un mal presagio.", 2, "|cFFFFD200Vendedor: |rLelanai|n|cFFFFD200Zona: |rTeldrassil|n|cFFFFD200Coste: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t" },
    [66906] = { 35179, 2, 0, "Destrero argenta", "Entrenado para aceptar únicamente a paladines de la Luz como jinetes.", 2, "|cFFFFD200Vendedor: |rDama Evniki Kapsalis|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t|n" },
