    [67336] = { 35362, 1, 192, "Fiel vástago de escarcha incansable", "En vida no pudo ser domado, pero la nigromancia y los rituales esotéricos de atadura se han combinado ahora para someter a esta indomable criatura a la voluntad de su jinete.", 5, "|cFFFFD200Legado|r" },
    [67466] = { 35445, 2, 0, "Caballo de guerra argenta", "Otorgado solo a aquellos que demuestran ser campeones en el Torneo Argenta.", 2, "|cFFFFD200Vendedor: |rDama Evniki Kapsalis|n|cFFFFD200Zona: |rCorona de Hielo|n|cFFFFD200Coste: |r100|TINTERFACE\\ICONS\\Ability_Paladin_ArtofWar.blp:0|t" },
    [68056] = { 35809, 2, 4, "Lobo de la Horda presto", "Algunas de las monturas más veloces de la Cruzada Argenta fueron otorgadas a aquellos miembros de la Horda que se desempeñaron de manera excepcional durante el torneo en Corona de Hielo.", 0, "|cFFFFD200Botín: |rCofre de tributo de la Cruzada Argenta|n|cFFFFD200Ubicación: |rPrueba del Gran Cruzado (10 jugadores)" },
    [68057] = { 35808, 2, 4, "Corcel de la Alianza presto", "Algunas de las monturas más veloces de la Cruzada Argenta fueron otorgadas a aquellos miembros de la Alianza que se desempeñaron de manera excepcional durante el torneo en Corona de Hielo.", 0, "|cFFFFD200Botín: |rCofre de tributo de la Cruzada Argenta|n|cFFFFD200Ubicación: |rPrueba del Gran Cruzado (10 jugadores)" },
    [68187] = { 35876, 2, 4, "Caballo de guerra blanco de cruzado", "Otorgados únicamente a los campeones más diestros de la Prueba del Cruzado, estos corceles fueron elegidos para miembros de la Alianza del establo personal de Tirion Vadín.", 5, "|cFFFFD200Logro: |rTributo a la inmortalidad|n|cFFFFD200Categoría: |rProezas de fuerza" },
    [68188] = { 35878, 2, 4, "Caballo de guerra negro de cruzado", "Otorgados únicamente a los campeones más diestros de la Prueba del Cruzado, estos corceles fueron elegidos para miembros de la Horda del establo personal de Tirion Vadín.", 5, "|cFFFFD200Logro: |rTributo a la inmortalidad|n|cFFFFD200Categoría: |rProezas de fuerza" },
