    [69395] = { 36837, 1, 128, "Draco onyxiano", "Tiene mucho en común con su madre, excepto por el hecho de haber sido asesinada y reanimada. Pero todavía es joven. -Maloriak", 0, "|cFFFFD200Botín: |rOnyxia|n|cFFFFD200Zona: |rGuarida de Onyxia" },
