    [71810] = { 38361, 1, 192, "Fiel vástago de escarcha colérico", "Muchos creen que en sus primeros años de vida estos vermis se vieron obligados a luchar contra los de su propia especie para diversión de otros. Quizá por eso poseen un temperamento particularmente combativo.", 5, "|cFFFFD200Legado|r" },
