    [72286] = { 38545, 2, 0, "Invencible", "El famoso corcel de Arthas Menethil, que sirve a su amo en la vida y en la muerte. Montarlo es verdaderamente una proeza de fuerza.", 0, "|cFFFFD200Botín: |rEl Rey Exánime|n|cFFFFD200Zona: |rCiudadela de la Corona de Hielo" },
    [72807] = { 38695, 1, 128, "Vencedor de la prole de escarcha vinculado al hielo", "Alzados de las gélidas profundidades de Corona de Hielo, los vencedores de la prole de escarcha se consideran entre los más feroces e implacables de todos los vermis de escarcha.", 5, "|cFFFFD200Logro: |rLa gloria del bandido de Corona de Hielo (25 jugadores)|n|cFFFFD200Categoría: |rMazmorras y bandas" },
    [72808] = { 38778, 1, 128, "Vencedor de la prole de escarcha bañado en sangre", "Los vencedores bañados en sangre reciben ese nombre cuando se determina que un vermis de escarcha reanimado murió de una forma particularmente espantosa y sangrienta.", 5, "|cFFFFD200Logro: |rLa gloria del bandido de Corona de Hielo (10 jugadores)|n|cFFFFD200Categoría: |rMazmorras y bandas" },
    [73313] = { 39046, 2, 0, "Destrero de la muerte carmesí", "Estabulado en la Ciudadela de la Corona de Hielo para servir a los esbirros predilectos del Rey Exánime.", 1, "|cFFFFD200Misión: |rEl reencuentro de Mograine|n|cFFFFD200Zona: |rCiudadela de la Corona de Hielo" },
