    [74856] = { 40165, 1, 192, "Hipogrifo llameante", "Los hipogrifos son seres altamente inteligentes y conscientes; mucho más que meras \"monturas\".", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r Hipogrifo llameante" },
    [74918] = { 40191, 2, 64, "Rinoceronte blanco lanudo", "Capturado por Toby \"Mamá Oca\" Cierreférreo en la Tundra Boreal, esta bestia greñuda guarda un enorme rencor tras haber sido embridada por un gnomo.", 8, "|cFFFFD200Juego de Cartas Coleccionables:|r Rinoceronte blanco lanudo" },
