    [75596] = { 40533, 1, 1024, "Alfombra voladora congelada", "\"Recuerdo mi primera alfombra voladora... pelo de yeti y arpillera. Ni de lejos tan agradable como esta de aquí\". - Frozo el Renombrado", 3, "|cFFFFD200Profesión: |rSastrería" },
    [75614] = { 40625, 2, 0, "Corcel celestial", "Un faro de esperanza; una luz que guía en la oscuridad.", 9, "|cFFFFD200Tienda del juego|r" },
